python3 -c "
import json, csv, os

experiments = {
    'vanilla': '/tmp/training_dynamics/vanilla.csv',
    'taxei_50': '/tmp/training_dynamics/taxei_50.csv',
    'random_10': '/tmp/training_dynamics/random_10.csv',
    'random_25': '/tmp/training_dynamics/random_25.csv',
    'random_50': '/tmp/training_dynamics/random_50.csv',
}

result = {}
for key, path in experiments.items():
    entries = []
    with open(path) as f:
        for line in f:
            parts = line.strip().split(',')
            if len(parts) == 3:
                entries.append({
                    'step': int(parts[0]),
                    'loss': float(parts[1]),
                    'token_acc': float(parts[2])
                })
    result[key] = entries
    print(f'{key}: {len(entries)} points, loss {entries[0][\"loss\"]:.3f}->{entries[-1][\"loss\"]:.3f}, acc {entries[0][\"token_acc\"]:.3f}->{entries[-1][\"token_acc\"]:.3f}')

# Add metadata
output = {
    'metadata': {
        'description': 'Training dynamics for dose-response experiments (fixed 4358 samples, seed=42)',
        'model': 'Qwen3-8B',
        'training_config': {
            'lora_rank': 16,
            'epochs': 3,
            'batch_size': 1,
            'grad_accum': 8,
            'lr': 1e-4,
            'seed': 42,
            'total_steps': 1635,
            'log_every': 5
        },
        'missing_experiments': {
            'taxei_10': 'OOM during training - no data available',
            'taxei_25': 'OOM during training - no data available'
        },
        'collected_at': '2026-05-15'
    },
    'experiments': result
}

outpath = '/tmp/training_dynamics/training_dynamics_dose_response.json'
with open(outpath, 'w') as f:
    json.dump(output, f, indent=2)

print(f'\nTotal size: {os.path.getsize(outpath)} bytes')
"
